#keysUnifiedPrototype .ka-reward{border:1px solid var(--color-brand-line);border-radius:20px;background:var(--color-card);overflow:hidden}
#keysUnifiedPrototype .ka-reward-main{padding:16px}
#keysUnifiedPrototype .ka-reward-heading{display:flex;align-items:center;gap:8px}
#keysUnifiedPrototype .ka-reward-heading>svg{width:20px;height:20px;color:var(--color-brand)}
#keysUnifiedPrototype#keysUnifiedPrototype .ka-home .ka-reward-heading h2{font-size:var(--text-14)!important;line-height:var(--leading-normal)!important}
#keysUnifiedPrototype .ka-reward-heading>span{display:flex;align-items:center;gap:4px;margin-left:auto;color:var(--color-success);font-size:var(--text-12);line-height:var(--leading-normal)}
#keysUnifiedPrototype .ka-reward-heading>span svg{width:12px;height:12px}
#keysUnifiedPrototype .ka-reward-benefit{display:flex;align-items:center;gap:16px;margin-top:16px}
#keysUnifiedPrototype .ka-reward-amount{display:grid;gap:2px;margin:0;color:var(--color-brand);flex:none;min-width:90px}
#keysUnifiedPrototype#keysUnifiedPrototype .ka-reward-amount strong{font-size:var(--text-20)!important;line-height:var(--leading-tight)!important;font-weight:var(--font-weight-medium)!important;font-variant-numeric:tabular-nums}
#keysUnifiedPrototype .ka-reward-amount>span{font-size:var(--text-12);line-height:var(--leading-normal)}
#keysUnifiedPrototype#keysUnifiedPrototype .ka-reward-copy{margin:0;padding-left:16px;border-left:1px solid var(--color-brand-line);color:var(--color-ink);font-size:var(--text-14)!important;font-weight:400;line-height:var(--leading-normal)!important}
#keysUnifiedPrototype .ka-reward-actions{position:relative;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px 16px;background:var(--color-soft);border-top:1px dashed var(--color-brand-line)}
#keysUnifiedPrototype .ka-reward-actions:before,#keysUnifiedPrototype .ka-reward-actions:after{content:"";position:absolute;top:-7px;width:12px;height:12px;border:1px solid var(--color-brand-line);background:var(--color-card);border-radius:50%;pointer-events:none}
#keysUnifiedPrototype .ka-reward-actions:before{left:-7px}
#keysUnifiedPrototype .ka-reward-actions:after{right:-7px}
#keysUnifiedPrototype .ka-reward-actions>.kh-detail-link{min-height:44px;padding:0;border:0;background:transparent}
#keysUnifiedPrototype .ka-home .ka-reward-search{min-height:44px;padding:10px 12px;border:0;border-radius:12px;background:var(--color-brand-solid);color:var(--color-on-brand);font-size:var(--text-12);font-weight:var(--font-weight-medium)}
@media(max-width:359px){#keysUnifiedPrototype .ka-reward-heading{gap:6px;flex-wrap:wrap}#keysUnifiedPrototype .ka-reward-heading>span{margin-left:26px;flex-basis:100%}#keysUnifiedPrototype .ka-reward-benefit{gap:12px}#keysUnifiedPrototype .ka-reward-copy{padding-left:12px}}
